script:
(function () {
  'use strict';
  // Refinance comparison: current loan (balance, rate, time left) vs a new loan.
  //   Payment: M = L * i / (1 - (1 + i)^-n), i = annual rate / 12 (M = L / n at 0%).
  //   Points cost = points% * new loan. If costs are rolled in, new loan = (balance + cash out +
  //   other costs) / (1 - points%), so the points are charged on the final loan amount.
  //   Break-even months = total closing costs / monthly payment saving (rounded up).
  //   Lifetime difference = remaining current payments - (new payments + costs paid in cash).
  // Verified in Node (scratchpad tests): $250,000 at 7% over 25 yrs = $1,766.95/mo; $250,000 at 6%
  //   over 30 yrs = $1,498.88/mo; break-even = ceil($5,500 / $268.07) = 21 months for the defaults;
  //   $200,000 at 0% over 20 yrs = $833.33/mo; costs rolled in at 1 point give ($253,000 / 0.99) =
  //   $255,555.56 with points of exactly 1% of it; year-by-year balances end at 0; no NaN/Infinity
  //   on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  // Balance after each month, index 0 = starting balance.
  function balances(loan, annualRate, months, pay) {
    var i = annualRate / 12, bal = loan, out = [bal];
    for (var m = 1; m <= months; m++) {
      bal = bal + bal * i - pay;
      if (bal < 0.005 || m === months) bal = 0;
      out.push(bal);
    }
    return out;
  }

  function refinance(o) {
    var curN = o.monthsLeft, newN = o.newYears * 12, p = o.points / 100;
    var curPay = monthlyPayment(o.balance, o.rate / 100, curN);
    var newLoan = o.roll ? (o.balance + o.cashOut + o.otherCosts) / (1 - p) : o.balance + o.cashOut;
    var pointsCost = newLoan * p, closing = pointsCost + o.otherCosts;
    var newPay = monthlyPayment(newLoan, o.newRate / 100, newN);
    var saving = curPay - newPay;
    var upfrontCash = o.roll ? 0 : closing;
    var curTotal = curPay * curN, newTotal = newPay * newN;
    return {
      curPay: curPay, newPay: newPay, saving: saving, newLoan: newLoan, pointsCost: pointsCost,
      closing: closing, upfrontCash: upfrontCash, curN: curN, newN: newN,
      curInterest: curTotal - o.balance, newInterest: newTotal - newLoan,
      curTotal: curTotal, newTotal: newTotal + upfrontCash,
      lifetime: curTotal - (newTotal + upfrontCash),
      breakEven: saving > 0.005 ? Math.ceil(closing / saving - 1e-9) : null,
      curBal: balances(o.balance, o.rate / 100, curN, curPay),
      newBal: balances(newLoan, o.newRate / 100, newN, newPay)
    };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function setText(id, text) { el(id).textContent = text; }

  var IDS = ['rfNewPayment', 'rfMonthlyChange', 'rfBreakEven', 'rfLifetime', 'rfCurLoan', 'rfNewLoan',
    'rfCurPay', 'rfNewPay', 'rfCurTerm', 'rfNewTerm2', 'rfCurInterest', 'rfNewInterest', 'rfCurCosts',
    'rfNewCosts', 'rfCurTotal', 'rfNewTotal', 'rfPointsCost'];

  function clearResults() {
    IDS.forEach(function (id) { setText(id, '–'); });
    el('rfYears').innerHTML = '';
  }

  function update() {
    var o = {
      balance: read('rfBalance'), rate: read('rfRate'), newRate: read('rfNewRate'), newYears: read('rfNewYears'),
      points: read('rfPoints', true), otherCosts: read('rfCosts', true), cashOut: read('rfCashOut', true),
      roll: el('rfRoll').checked
    };
    var yearsLeft = read('rfYearsLeft', true), monthsLeft = read('rfMonthsLeft', true);
    o.monthsLeft = yearsLeft * 12 + monthsLeft;
    var error = el('rfError'), msg = '';
    if (isNaN(o.balance) || o.balance <= 0) msg = 'Enter a current loan balance greater than $0.';
    else if (isNaN(o.rate) || o.rate < 0 || o.rate > 30 || isNaN(o.newRate) || o.newRate < 0 || o.newRate > 30) msg = 'Enter interest rates from 0% to 30%.';
    else if (isNaN(yearsLeft) || isNaN(monthsLeft) || yearsLeft < 0 || monthsLeft < 0 || yearsLeft % 1 !== 0 || monthsLeft % 1 !== 0 || monthsLeft > 11 || o.monthsLeft < 1 || o.monthsLeft > 600) msg = 'Enter the time left as whole years and months (0 to 11), at least 1 month in total.';
    else if (isNaN(o.newYears) || o.newYears < 1 || o.newYears > 50 || o.newYears % 1 !== 0) msg = 'Enter a new loan term of 1 to 50 whole years.';
    else if ([o.points, o.otherCosts, o.cashOut].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Points, costs and cash out cannot be negative.';
    else if (o.points > 10) msg = 'Enter 10 points or fewer.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var r = refinance(o);
    setText('rfNewPayment', money.format(r.newPay));
    setText('rfMonthlyChange', r.saving >= 0.005 ? money.format(r.saving) + ' lower' :
      (r.saving <= -0.005 ? money.format(-r.saving) + ' higher' : 'No change'));
    setText('rfBreakEven', r.breakEven === null ? 'Not reached' : (r.breakEven === 0 ? 'Immediately' : duration(r.breakEven)));
    setText('rfLifetime', r.lifetime >= 0.005 ? 'Save ' + money.format(r.lifetime) :
      (r.lifetime <= -0.005 ? 'Pay ' + money.format(-r.lifetime) + ' more' : 'No difference'));
    setText('rfCurLoan', money.format(o.balance));
    setText('rfNewLoan', money.format(r.newLoan));
    setText('rfCurPay', money.format(r.curPay));
    setText('rfNewPay', money.format(r.newPay));
    setText('rfCurTerm', duration(r.curN));
    setText('rfNewTerm2', duration(r.newN));
    setText('rfCurInterest', money.format(r.curInterest));
    setText('rfNewInterest', money.format(r.newInterest));
    setText('rfCurCosts', money.format(0));
    setText('rfNewCosts', money.format(r.closing) + (o.roll ? ' (in loan)' : ''));
    setText('rfCurTotal', money.format(r.curTotal));
    setText('rfNewTotal', money.format(r.newTotal));
    setText('rfPointsCost', money.format(r.pointsCost));

    var html = [], maxN = Math.max(r.curN, r.newN), years = Math.ceil(maxN / 12);
    for (var y = 1; y <= years; y++) {
      var m = Math.min(y * 12, maxN);
      var cur = r.curPay * Math.min(m, r.curN), nw = r.newPay * Math.min(m, r.newN) + r.upfrontCash;
      var diff = cur - nw;
      html.push('<tr><td>' + y + '</td><td>' + money.format(r.curBal[Math.min(m, r.curN)]) + '</td><td>' +
        money.format(r.newBal[Math.min(m, r.newN)]) + '</td><td>' + (diff < -0.005 ? '−' : '') +
        money.format(Math.abs(diff)) + '</td></tr>');
    }
    el('rfYears').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('rfForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
